-- v4.4.10 complete model governance: quota, replay, finance, evidence, and wallboard versions.
DECLARE c NUMBER; BEGIN
 SELECT COUNT(*) INTO c FROM USER_TAB_COLUMNS WHERE TABLE_NAME='CX_MODEL_REQUESTS' AND COLUMN_NAME='CORRELATION_ID'; IF c=0 THEN EXECUTE IMMEDIATE 'ALTER TABLE CX_MODEL_REQUESTS ADD (CORRELATION_ID VARCHAR2(128))'; END IF;
 SELECT COUNT(*) INTO c FROM USER_TAB_COLUMNS WHERE TABLE_NAME='CX_MODEL_REQUESTS' AND COLUMN_NAME='CREDENTIAL_ID'; IF c=0 THEN EXECUTE IMMEDIATE 'ALTER TABLE CX_MODEL_REQUESTS ADD (CREDENTIAL_ID VARCHAR2(128))'; END IF;
END;
/
DECLARE n NUMBER; BEGIN
 SELECT COUNT(*) INTO n FROM USER_TABLES WHERE TABLE_NAME='CX_MODEL_QUOTA_POLICIES'; IF n=0 THEN EXECUTE IMMEDIATE 'CREATE TABLE CX_MODEL_QUOTA_POLICIES (POLICY_ID VARCHAR2(128) PRIMARY KEY,POLICY_KEY VARCHAR2(128) NOT NULL,VERSION NUMBER NOT NULL,SCOPE_TYPE VARCHAR2(32) NOT NULL,SCOPE_ID VARCHAR2(128),METRIC VARCHAR2(16) NOT NULL,LIMIT_VALUE NUMBER(24,6) NOT NULL,CURRENCY VARCHAR2(12),ENFORCEMENT VARCHAR2(16) NOT NULL,WINDOW_TYPE VARCHAR2(16) NOT NULL,RESERVATION_VALUE NUMBER(24,6) NOT NULL,INCOMPLETE_POLICY VARCHAR2(24) NOT NULL,EFFECTIVE_FROM TIMESTAMP NOT NULL,EFFECTIVE_TO TIMESTAMP,STATUS VARCHAR2(24) NOT NULL,CREATED_BY VARCHAR2(128) NOT NULL,REASON VARCHAR2(500) NOT NULL,CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,CONSTRAINT CX_MQP_UQ UNIQUE(POLICY_KEY,VERSION),CONSTRAINT CX_MQP_LIMIT_CK CHECK(LIMIT_VALUE>=0),CONSTRAINT CX_MQP_RES_CK CHECK(RESERVATION_VALUE>=0))'; END IF;
 SELECT COUNT(*) INTO n FROM USER_TABLES WHERE TABLE_NAME='CX_MODEL_QUOTA_RESERVATIONS'; IF n=0 THEN EXECUTE IMMEDIATE 'CREATE TABLE CX_MODEL_QUOTA_RESERVATIONS (RESERVATION_ID VARCHAR2(128) PRIMARY KEY,REQUEST_ID VARCHAR2(128) NOT NULL,POLICY_ID VARCHAR2(128) NOT NULL,WINDOW_START TIMESTAMP NOT NULL,WINDOW_END TIMESTAMP NOT NULL,RESERVED_VALUE NUMBER(24,6) NOT NULL,SETTLED_VALUE NUMBER(24,6),STATUS VARCHAR2(24) NOT NULL,WARNING VARCHAR2(500),EXPIRES_AT TIMESTAMP NOT NULL,CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,UPDATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,CONSTRAINT CX_MQR_UQ UNIQUE(REQUEST_ID,POLICY_ID),CONSTRAINT CX_MQR_VAL_CK CHECK(RESERVED_VALUE>=0))'; END IF;
 SELECT COUNT(*) INTO n FROM USER_TABLES WHERE TABLE_NAME='CX_MODEL_REPLAY_SNAPSHOTS'; IF n=0 THEN EXECUTE IMMEDIATE 'CREATE TABLE CX_MODEL_REPLAY_SNAPSHOTS (REQUEST_ID VARCHAR2(128) PRIMARY KEY,RESPONSE_CIPHER CLOB NOT NULL,RESPONSE_DIGEST VARCHAR2(128) NOT NULL,KEY_REFERENCE VARCHAR2(128) NOT NULL,BYTE_COUNT NUMBER NOT NULL,EXPIRES_AT TIMESTAMP NOT NULL,CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,CONSTRAINT CX_MRS_SIZE_CK CHECK(BYTE_COUNT BETWEEN 0 AND 1048576))'; END IF;
 SELECT COUNT(*) INTO n FROM USER_TABLES WHERE TABLE_NAME='CX_PROVIDER_INVOICE_BATCHES'; IF n=0 THEN EXECUTE IMMEDIATE 'CREATE TABLE CX_PROVIDER_INVOICE_BATCHES (BATCH_ID VARCHAR2(128) PRIMARY KEY,PROVIDER_KEY VARCHAR2(128) NOT NULL,EXTERNAL_INVOICE_ID VARCHAR2(160) NOT NULL,SOURCE_DIGEST VARCHAR2(128) NOT NULL,CURRENCY VARCHAR2(12) NOT NULL,PERIOD_START TIMESTAMP NOT NULL,PERIOD_END TIMESTAMP NOT NULL,TOTAL_AMOUNT NUMBER(24,6) NOT NULL,STATUS VARCHAR2(24) NOT NULL,IMPORTED_BY VARCHAR2(128) NOT NULL,REASON VARCHAR2(500) NOT NULL,CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,CONSTRAINT CX_PIB_UQ UNIQUE(PROVIDER_KEY,EXTERNAL_INVOICE_ID))'; END IF;
 SELECT COUNT(*) INTO n FROM USER_TABLES WHERE TABLE_NAME='CX_PROVIDER_INVOICE_LINES'; IF n=0 THEN EXECUTE IMMEDIATE 'CREATE TABLE CX_PROVIDER_INVOICE_LINES (LINE_ID VARCHAR2(128) PRIMARY KEY,BATCH_ID VARCHAR2(128) NOT NULL,EXTERNAL_LINE_ID VARCHAR2(160) NOT NULL,MODEL_ID VARCHAR2(256),QUANTITY NUMBER(24,6),AMOUNT NUMBER(24,6) NOT NULL,CURRENCY VARCHAR2(12) NOT NULL,LINE_DIGEST VARCHAR2(128) NOT NULL,CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,CONSTRAINT CX_PIL_UQ UNIQUE(BATCH_ID,EXTERNAL_LINE_ID))'; END IF;
 SELECT COUNT(*) INTO n FROM USER_TABLES WHERE TABLE_NAME='CX_MODEL_RECONCILIATIONS'; IF n=0 THEN EXECUTE IMMEDIATE 'CREATE TABLE CX_MODEL_RECONCILIATIONS (RECONCILIATION_ID VARCHAR2(128) PRIMARY KEY,LINE_ID VARCHAR2(128) NOT NULL,USAGE_ID VARCHAR2(128),RULE_VERSION VARCHAR2(64) NOT NULL,CONFIDENCE NUMBER(8,6),INVOICE_AMOUNT NUMBER(24,6) NOT NULL,CALCULATED_AMOUNT NUMBER(24,6),VARIANCE_AMOUNT NUMBER(24,6),STATUS VARCHAR2(24) NOT NULL,CREATED_BY VARCHAR2(128) NOT NULL,REASON VARCHAR2(500) NOT NULL,CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,CONSTRAINT CX_MREC_UQ UNIQUE(LINE_ID,USAGE_ID,RULE_VERSION))'; END IF;
 SELECT COUNT(*) INTO n FROM USER_TABLES WHERE TABLE_NAME='CX_PROVIDER_INVOICE_CORRECTIONS'; IF n=0 THEN EXECUTE IMMEDIATE 'CREATE TABLE CX_PROVIDER_INVOICE_CORRECTIONS (CORRECTION_ID VARCHAR2(128) PRIMARY KEY,LINE_ID VARCHAR2(128) NOT NULL,PRIOR_CORRECTION_ID VARCHAR2(128),AMOUNT_DELTA NUMBER(24,6) NOT NULL,CURRENCY VARCHAR2(12) NOT NULL,CREATED_BY VARCHAR2(128) NOT NULL,REASON VARCHAR2(500) NOT NULL,CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,CONSTRAINT CX_PIC_DELTA_CK CHECK(AMOUNT_DELTA<>0))'; END IF;
 SELECT COUNT(*) INTO n FROM USER_TABLES WHERE TABLE_NAME='CX_MODEL_ALLOCATION_RULES'; IF n=0 THEN EXECUTE IMMEDIATE 'CREATE TABLE CX_MODEL_ALLOCATION_RULES (RULE_ID VARCHAR2(128) PRIMARY KEY,RULE_KEY VARCHAR2(128) NOT NULL,VERSION NUMBER NOT NULL,TARGET_TYPE VARCHAR2(32) NOT NULL,TARGET_ID VARCHAR2(128) NOT NULL,PERCENTAGE NUMBER(9,6) NOT NULL,CURRENCY VARCHAR2(12),EFFECTIVE_FROM TIMESTAMP NOT NULL,EFFECTIVE_TO TIMESTAMP,STATUS VARCHAR2(24) NOT NULL,CREATED_BY VARCHAR2(128) NOT NULL,REASON VARCHAR2(500) NOT NULL,CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,CONSTRAINT CX_MAR_UQ UNIQUE(RULE_KEY,VERSION,TARGET_TYPE,TARGET_ID),CONSTRAINT CX_MAR_PCT_CK CHECK(PERCENTAGE BETWEEN 0 AND 100))'; END IF;
 SELECT COUNT(*) INTO n FROM USER_TABLES WHERE TABLE_NAME='CX_MODEL_ALLOCATIONS'; IF n=0 THEN EXECUTE IMMEDIATE 'CREATE TABLE CX_MODEL_ALLOCATIONS (ALLOCATION_ID VARCHAR2(128) PRIMARY KEY,SOURCE_TYPE VARCHAR2(16) NOT NULL,SOURCE_ID VARCHAR2(128) NOT NULL,RULE_ID VARCHAR2(128) NOT NULL,TARGET_TYPE VARCHAR2(32) NOT NULL,TARGET_ID VARCHAR2(128) NOT NULL,AMOUNT NUMBER(24,6) NOT NULL,CURRENCY VARCHAR2(12) NOT NULL,REMAINDER CHAR(1) DEFAULT ''N'' NOT NULL,CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,CONSTRAINT CX_MALLOC_UQ UNIQUE(SOURCE_TYPE,SOURCE_ID,RULE_ID,TARGET_TYPE,TARGET_ID))'; END IF;
 SELECT COUNT(*) INTO n FROM USER_TABLES WHERE TABLE_NAME='CX_MODEL_EVIDENCE_ADAPTERS'; IF n=0 THEN EXECUTE IMMEDIATE 'CREATE TABLE CX_MODEL_EVIDENCE_ADAPTERS (ADAPTER_ID VARCHAR2(128) NOT NULL,DISPLAY_NAME VARCHAR2(160) NOT NULL,KEY_VERSION NUMBER NOT NULL,VERIFICATION_KEY CLOB NOT NULL,SCOPES_JSON CLOB NOT NULL,STATUS VARCHAR2(24) NOT NULL,CREATED_BY VARCHAR2(128) NOT NULL,CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,REVOKED_AT TIMESTAMP,REVOKED_BY VARCHAR2(128),REVOKE_REASON VARCHAR2(500),CONSTRAINT CX_MEA_PK PRIMARY KEY(ADAPTER_ID,KEY_VERSION))'; END IF;
 SELECT COUNT(*) INTO n FROM USER_TABLES WHERE TABLE_NAME='CX_MODEL_EVIDENCE_BATCHES'; IF n=0 THEN EXECUTE IMMEDIATE 'CREATE TABLE CX_MODEL_EVIDENCE_BATCHES (BATCH_ID VARCHAR2(128) PRIMARY KEY,ADAPTER_ID VARCHAR2(128) NOT NULL,KEY_VERSION NUMBER NOT NULL,SEQUENCE_NO NUMBER NOT NULL,NONCE VARCHAR2(128) NOT NULL,PAYLOAD_DIGEST VARCHAR2(128) NOT NULL,SIGNATURE_DIGEST VARCHAR2(128) NOT NULL,OBSERVED_FROM TIMESTAMP NOT NULL,OBSERVED_TO TIMESTAMP NOT NULL,PROVIDER_KEY VARCHAR2(128),AGENT_ID VARCHAR2(128),REQUEST_COUNT NUMBER NOT NULL,TOTAL_TOKENS NUMBER,USAGE_PROVENANCE VARCHAR2(32) NOT NULL,STATUS VARCHAR2(24) NOT NULL,CORRELATION_ID VARCHAR2(128) NOT NULL,CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,CONSTRAINT CX_MEB_SEQ_UQ UNIQUE(ADAPTER_ID,SEQUENCE_NO),CONSTRAINT CX_MEB_NONCE_UQ UNIQUE(ADAPTER_ID,NONCE),CONSTRAINT CX_MEB_COUNT_CK CHECK(REQUEST_COUNT>=0))'; END IF;
 SELECT COUNT(*) INTO n FROM USER_TABLES WHERE TABLE_NAME='CX_WALLBOARD_DEF_VERSIONS'; IF n=0 THEN EXECUTE IMMEDIATE 'CREATE TABLE CX_WALLBOARD_DEF_VERSIONS (VERSION_ID VARCHAR2(128) PRIMARY KEY,DEFINITION_ID VARCHAR2(128) NOT NULL,VERSION NUMBER NOT NULL,DISPLAY_NAME VARCHAR2(160) NOT NULL,CONFIG_JSON CLOB NOT NULL,SCOPE_JSON CLOB NOT NULL,STATUS VARCHAR2(24) NOT NULL,CREATED_BY VARCHAR2(128) NOT NULL,REASON VARCHAR2(500) NOT NULL,CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,CONSTRAINT CX_WDV_UQ UNIQUE(DEFINITION_ID,VERSION))'; END IF;
 SELECT COUNT(*) INTO n FROM USER_TABLES WHERE TABLE_NAME='CX_WALLBOARD_PUBLICATIONS'; IF n=0 THEN EXECUTE IMMEDIATE 'CREATE TABLE CX_WALLBOARD_PUBLICATIONS (PUBLICATION_ID VARCHAR2(128) PRIMARY KEY,DEFINITION_ID VARCHAR2(128) NOT NULL,VERSION_ID VARCHAR2(128) NOT NULL,STATUS VARCHAR2(24) NOT NULL,PUBLISHED_BY VARCHAR2(128) NOT NULL,REASON VARCHAR2(500) NOT NULL,CURRENT_MARKER VARCHAR2(128),PUBLISHED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,CONSTRAINT CX_WPUB_CUR_UQ UNIQUE(CURRENT_MARKER))'; END IF;
END;
/
DECLARE n NUMBER; BEGIN
 SELECT COUNT(*) INTO n FROM USER_INDEXES WHERE INDEX_NAME='CX_MODEL_QUOTA_WINDOW'; IF n=0 THEN EXECUTE IMMEDIATE 'CREATE INDEX CX_MODEL_QUOTA_WINDOW ON CX_MODEL_QUOTA_RESERVATIONS(POLICY_ID,WINDOW_START,STATUS)'; END IF;
 SELECT COUNT(*) INTO n FROM USER_INDEXES WHERE INDEX_NAME='CX_MODEL_EVIDENCE_TIME'; IF n=0 THEN EXECUTE IMMEDIATE 'CREATE INDEX CX_MODEL_EVIDENCE_TIME ON CX_MODEL_EVIDENCE_BATCHES(ADAPTER_ID,OBSERVED_TO,STATUS)'; END IF;
END;
/
MERGE INTO CX_PLATFORM_CAPABILITIES d USING (SELECT 'model_finance' CAPABILITY_KEY FROM DUAL) s ON (d.CAPABILITY_KEY=s.CAPABILITY_KEY) WHEN NOT MATCHED THEN INSERT (CAPABILITY_KEY,MANDATORY,ENABLED) VALUES (s.CAPABILITY_KEY,'N','Y');
MERGE INTO CX_PLATFORM_CAPABILITIES d USING (SELECT 'external_model_evidence' CAPABILITY_KEY FROM DUAL) s ON (d.CAPABILITY_KEY=s.CAPABILITY_KEY) WHEN NOT MATCHED THEN INSERT (CAPABILITY_KEY,MANDATORY,ENABLED) VALUES (s.CAPABILITY_KEY,'N','Y');
